/**
 * 解析一个可能带引号的变量名（IR 里既有 `"10"` 也有 `10`）。
 * 查不到返回 undefined —— 调用方**必须** fail-closed，绝不能当 0。
 */
export function outfitKeyId(
  table: Readonly<Record<string, number>>,
  key: string,
): number | undefined {
  if (/^-?\d+$/u.test(key)) return Number(key);
  return table[key];
}
